create table public.individual_catalog_releases (
 id uuid primary key default gen_random_uuid(), version text not null unique, document jsonb not null,
 published_at timestamptz not null default now(), published_by uuid
);
create table public.individual_catalog_state (
 id boolean primary key default true check(id), draft jsonb not null, revision bigint not null default 1,
 published_release_id uuid not null references public.individual_catalog_releases(id),
 updated_at timestamptz not null default now(), updated_by uuid
);
alter table public.individual_catalog_releases enable row level security;
alter table public.individual_catalog_state enable row level security;
revoke all on public.individual_catalog_releases,public.individual_catalog_state from public,anon,authenticated;
grant select,insert on public.individual_catalog_releases to service_role;
grant select,insert,update on public.individual_catalog_state to service_role;

create function public.individual_catalog_read() returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('version',r.version,'document',r.document,'published_at',r.published_at)
 from public.individual_catalog_state s join public.individual_catalog_releases r on r.id=s.published_release_id where s.id=true;
$$;
create function public.individual_catalog_save(p_document jsonb,p_expected bigint,p_actor uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare s public.individual_catalog_state;
begin
 select * into s from public.individual_catalog_state where id=true for update;
 if not found then raise exception 'CATALOG_UNAVAILABLE'; end if;
 if s.revision<>p_expected then raise exception 'CATALOG_CONFLICT'; end if;
 if jsonb_typeof(p_document)<>'object' then raise exception 'INVALID_CATALOG'; end if;
 update public.individual_catalog_state set draft=p_document,revision=revision+1,updated_at=now(),updated_by=p_actor where id=true returning * into s;
 return jsonb_build_object('revision',s.revision);
end; $$;
create function public.individual_catalog_publish(p_expected bigint,p_actor uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare s public.individual_catalog_state; r public.individual_catalog_releases;
begin
 select * into s from public.individual_catalog_state where id=true for update;
 if not found then raise exception 'CATALOG_UNAVAILABLE'; end if;
 if s.revision<>p_expected then raise exception 'CATALOG_CONFLICT'; end if;
 insert into public.individual_catalog_releases(version,document,published_by)
 values('catalog-'||gen_random_uuid()::text,s.draft,p_actor) returning * into r;
 update public.individual_catalog_state set published_release_id=r.id,revision=revision+1,updated_at=now(),updated_by=p_actor where id=true returning * into s;
 return jsonb_build_object('revision',s.revision,'version',r.version,'published_at',r.published_at);
end; $$;
revoke all on function public.individual_catalog_read(),public.individual_catalog_save(jsonb,bigint,uuid),public.individual_catalog_publish(bigint,uuid) from public,anon,authenticated;
grant execute on function public.individual_catalog_read(),public.individual_catalog_save(jsonb,bigint,uuid),public.individual_catalog_publish(bigint,uuid) to service_role;

